  load.innerHTML='<strong>'+fmtAmount(known,kind)+' / '+(kind==='asphalt'?tg.toFixed(0)+' tons':(kind==='seed'||kind==='sod')?tg.toFixed(0)+' SF':kind==='sawcutting'?tg.toFixed(0)+' stops':tg.toFixed(1)+' CY')+'</strong><span>'+(kind==='sawcutting'?'flagged properties':pct+'% of day')+(unknown?' · ⚠ '+unknown+' stop'+(unknown===1?'':'s')+' need '+(kind==='concrete'?'yards':'quantity'):'')+'</span><div class="routeCapacityBar"><i style="width:'+Math.min(100,pct)+'%"></i></div>';
  av.querySelectorAll('[data-add-stop]').forEach(b=>b.onclick=()=>{selected.push(Number(b.dataset.addStop));draw()});
  sel.querySelectorAll('[data-remove-stop]').forEach(b=>b.onclick=()=>{selected=selected.filter(x=>x!==Number(b.dataset.removeStop));draw()});
