let verifierRouteIds=[];
let verifierRoutePosition=0;
function verifierRouteAddress(j){return [j.address,j.city,'Michigan'].filter(Boolean).join(', ')}
function verifierRouteSave(){
 try{localStorage.setItem('dangelo_field_verify_route',JSON.stringify({ids:verifierRouteIds,position:verifierRoutePosition}))}catch(e){}
}
function verifierRouteLoad(){
 try{const r=JSON.parse(localStorage.getItem('dangelo_field_verify_route')||'{}');verifierRouteIds=Array.isArray(r.ids)?r.ids.map(Number).filter(id=>jobs.some(j=>j.id===id)):[];verifierRoutePosition=Math.max(0,Math.min(verifierRouteIds.length-1,Number(r.position)||0))}catch(e){verifierRouteIds=[];verifierRoutePosition=0}
}
function spanishVerifierPage(){
 const host=document.getElementById('restorationPage');if(!host)return;
 verifierRouteLoad();
 const term=t=>({seed:'Semilla',sod:'Césped en rollo',asphalt:'Asfalto',concrete:'Concreto',composite:'Pavimento mixto'}[t]||t);
 const cities=[...new Set(jobs.map(j=>j.city).filter(Boolean))].sort((a,b)=>a.localeCompare(b));
 host.innerHTML='<div class="restHead"><h2>VERIFICACIÓN EN CAMPO</h2></div><div class="fvRoutePanel" style="padding:12px;margin:12px;border:1px solid #ddd;border-radius:9px;background:#f7f7f7"><h3 style="margin:0 0 12px">Planear recorrido</h3><label>Ciudad<select id="fvCity" style="display:block;width:100%;padding:10px;margin:5px 0 10px"><option value="all">Todas las ciudades</option>'+cities.map(c=>'<option value="'+esc(c)+'">'+esc(c)+'</option>').join('')+'</select></label><label><input id="fvPending" type="checkbox" checked> Solo direcciones sin verificar</label><label style="display:block;margin:10px 0">Paradas (máximo 20) <select id="fvLimit" style="padding:8px"><option value="10">10</option><option value="15" selected>15</option><option value="20">20</option></select></label><button type="button" id="fvBuildRoute" class="restPrimary">Crear ruta optimizada</button><div id="fvRouteMessage" role="status" style="margin-top:8px"></div><div id="fvActiveRoute"></div></div><div style="padding:12px"><input id="fvSearch" placeholder="Buscar dirección..." style="width:100%;padding:12px;font-size:16px"><div id="fvList"></div></div>';
 const searchBox=host.querySelector('#fvSearch'),list=host.querySelector('#fvList');
 const citySel=host.querySelector('#fvCity'),pending=host.querySelector('#fvPending'),limit=host.querySelector('#fvLimit'),status=host.querySelector('#fvRouteMessage'),routeHost=host.querySelector('#fvActiveRoute');
 const work=j=>items.filter(i=>i.restoration_job_id===j.id);
 function draw(){
   const q=searchBox.value.toLowerCase().trim();
   const matched=jobs.filter(j=>(citySel.value==='all'||j.city===citySel.value)&&(!pending.checked||!j.field_verified_at)&&(!q||[j.address,j.job_name].some(v=>String(v||'').toLowerCase().includes(q)))).slice(0,150);
   list.innerHTML=matched.map(j=>'<button type="button" class="restCard'+(j.priority==='urgent'?' urgent':'')+'" data-fvjob="'+j.id+'" style="width:100%;text-align:left;margin:10px 0;padding:15px"><strong>'+esc(j.address||j.job_name)+'</strong><div class="restItems">'+work(j).map(i=>'<span>'+esc(term(i.type))+(i.subtype?' / '+esc(i.subtype):'')+' — '+restorationCardQuantity(i)+'</span>').join('')+'</div><small>'+(j.field_verified_at?'✓ Verificado '+new Date(j.field_verified_at).toLocaleDateString('es-MX'):'Pendiente de verificar')+'</small></button>').join('');
   list.querySelectorAll('[data-fvjob]').forEach(b=>b.onclick=()=>openVerifierJob(jobs.find(j=>j.id===Number(b.dataset.fvjob))));
   drawRoute();
 }
 function drawRoute(){
   if(!verifierRouteIds.length){routeHost.innerHTML='';return}
   const j=jobs.find(x=>x.id===verifierRouteIds[verifierRoutePosition]);
   if(!j){verifierRouteIds=[];verifierRouteSave();routeHost.innerHTML='';return}
   const total=verifierRouteIds.length;
   routeHost.innerHTML='<div style="border-top:1px solid #ddd;margin-top:12px;padding-top:12px"><b>Parada '+(verifierRoutePosition+1)+' de '+total+'</b><div style="font-size:18px;font-weight:800;margin:8px 0">'+esc(j.address||j.job_name)+'</div><div>'+esc(j.city||'')+(j.priority==='urgent'?' · <b style="color:#b42318">URGENTE</b>':'')+(j.field_verified_at?' · ✓ Verificado':'')+'</div><div style="display:flex;gap:8px;flex-wrap:wrap;margin:12px 0"><button type="button" id="fvNavigate" class="restPrimary">Navegar</button><button type="button" id="fvInspect" class="restPrimary">Verificar</button><button type="button" id="fvPrev" '+(verifierRoutePosition===0?'disabled':'')+'>Anterior</button><button type="button" id="fvNext" '+(verifierRoutePosition===total-1?'disabled':'')+'>Siguiente</button></div><details><summary>Ver las '+total+' paradas</summary><div id="fvRouteStops">'+verifierRouteIds.map((id,i)=>{const stop=jobs.find(x=>x.id===id);return '<button type="button" data-fvstop="'+i+'" style="display:block;width:100%;padding:10px;margin:4px 0;text-align:left;border:1px solid #ddd;border-radius:5px;'+(i===verifierRoutePosition?'background:#fff4ce;':'')+'">'+(i+1)+'. '+esc(stop?.address||'')+(stop?.field_verified_at?' ✓':'')+'</button>'}).join('')+'</div></details><button id="fvClearRoute" type="button" style="margin-top:12px">Borrar ruta</button></div>';
   routeHost.querySelector('#fvNavigate').onclick=()=>window.open('https://www.google.com/maps/dir/?api=1&destination='+encodeURIComponent(verifierRouteAddress(j))+'&travelmode=driving&dir_action=navigate','_blank','noopener');
   routeHost.querySelector('#fvInspect').onclick=()=>openVerifierJob(j);
   const go=step=>{verifierRoutePosition=Math.max(0,Math.min(total-1,step));verifierRouteSave();drawRoute()};
   routeHost.querySelector('#fvPrev').onclick=()=>go(verifierRoutePosition-1);
   routeHost.querySelector('#fvNext').onclick=()=>go(verifierRoutePosition+1);
   routeHost.querySelectorAll('[data-fvstop]').forEach(b=>b.onclick=()=>go(Number(b.dataset.fvstop)));
   routeHost.querySelector('#fvClearRoute').onclick=()=>{verifierRouteIds=[];verifierRoutePosition=0;verifierRouteSave();drawRoute()};
 }
 host.querySelector('#fvBuildRoute').onclick=async()=>{
   const btn=host.querySelector('#fvBuildRoute');
   const candidates=jobs.filter(j=>j.address&&(citySel.value==='all'||j.city===citySel.value)&&(!pending.checked||!j.field_verified_at)).sort((a,b)=>(b.priority==='urgent')-(a.priority==='urgent')).slice(0,Number(limit.value));
   if(!candidates.length){status.textContent='No hay direcciones disponibles en esta selección.';return}
   btn.disabled=true;status.textContent='Calculando el mejor orden para conducir…';
   try{
     const res=await fetch('/api/build-asphalt-day',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({targetTons:candidates.length,anchorLocation:'all',candidates:candidates.map(j=>({id:j.id,address:j.address,city:j.city,project:j.project,state:'MI',tons:1,latitude:j.latitude,longitude:j.longitude,geocodedAddress:j.geocoded_address}))})});
     const out=await res.json();if(!res.ok)throw new Error(out.error||'No se pudo calcular la ruta');
     verifierRouteIds=(out.order||[]).map(Number);verifierRoutePosition=0;verifierRouteSave();drawRoute();
     status.textContent='Ruta preparada: '+verifierRouteIds.length+' paradas. Use Navegar para abrir Google Maps.';
   }catch(e){status.textContent='Error: '+e.message}finally{btn.disabled=false}
 };
 searchBox.oninput=draw;citySel.onchange=draw;pending.onchange=draw;draw();
}
