 const choices='<option value="seed">Semilla</option><option value="sod">Césped</option><option value="asphalt">Asfalto</option><option value="concrete|Sidewalk">Concreto / Banqueta</option><option value="concrete|Road">Concreto / Calle</option><option value="concrete|Driveway">Concreto / Entrada</option><option value="concrete|Approach">Concreto / Acceso</option><option value="composite">Pavimento mixto</option>';
