async function deleteRestLocation(name){
  if(!['supervisor','admin'].includes(role))return false;
  const used=jobs.filter(j=>String(j.project||'').trim().toLowerCase()===String(name).trim().toLowerCase());
  if(used.length){alert(name+' cannot be deleted because '+used.length+' restoration '+(used.length===1?'property is':'properties are')+' assigned to it. Reassign those properties first.');return false}
  if(!confirm('Delete city "'+name+'"? This will remove the location from the list.'))return false;
  try{
    await req('/rest/v1/restoration_projects?name=eq.'+encodeURIComponent(name),{method:'DELETE',headers:{Prefer:'return=representation'}});
    if(projectFilter===name)projectFilter='all';
    await load();
    return true;
  }catch(err){alert('Could not delete city: '+err.message);return false}
}
function openRestLocationMenu(name,x,y){
  if(!['supervisor','admin'].includes(role))return;
  document.querySelector('#restLocationContextMenu')?.remove();
  const menu=document.createElement('div');menu.id='restLocationContextMenu';
  menu.style.cssText='position:fixed;z-index:99999;background:#fff;border:1px solid #cbd5e1;border-radius:8px;box-shadow:0 5px 22px #0003;padding:5px;min-width:165px';
  const b=document.createElement('button');b.type='button';b.textContent='Delete City';
  b.style.cssText='display:block;width:100%;text-align:left;padding:9px 12px;color:#b91c1c;background:white;border:0;cursor:pointer;font-weight:600';
  b.onclick=async()=>{menu.remove();await deleteRestLocation(name)};
  menu.appendChild(b);document.body.appendChild(menu);
  menu.style.left=Math.max(4,Math.min(x,innerWidth-menu.offsetWidth-4))+'px';
  menu.style.top=Math.max(4,Math.min(y,innerHeight-menu.offsetHeight-4))+'px';
  const dismiss=e=>{if(!menu.contains(e.target))menu.remove()};
  setTimeout(()=>document.addEventListener('pointerdown',dismiss,{once:true}),0);
  document.addEventListener('keydown',e=>{if(e.key==='Escape')menu.remove()},{once:true});
}
