function hookJobModals(){const root=document.getElementById('modalRoot');if(!root||root.dataset.restHook)return;root.dataset.restHook='1';new MutationObserver(()=>{const actions=root.querySelector('.modalActions'),save=root.querySelector('#saveJob');if(!actions||!save||root.querySelector('#sendRestoration'))return;const id=Number(root.querySelector('#deleteJob')?.closest('.modal')?window.__x:0);const jobId=Number(root.querySelector('#deleteJob')?.id&&root.querySelector('#f_job_name')?document.querySelector('.modal')?.querySelector('#deleteJob')?0:0:0);const name=root.querySelector('#f_job_name');if(!name)return;const current=[...document.querySelectorAll('.jobCard')].map(x=>Number(x.dataset.jobId));const draftId=current.find(x=>{const card=document.querySelector(`.jobCard[data-job-id="${x}"]`);return card&&card.textContent.includes(name.value)})||null;if(!draftId)return;const b=document.createElement('button');b.id='sendRestoration';b.type='button';b.textContent='Send to Restoration';b.onclick=async()=>{try{const a=await req(`/rest/v1/jobs?id=eq.${draftId}&select=*`);if(a[0])openEditor(null,a[0])}catch{}};actions.insertBefore(b,save)}, {childList:true,subtree:true})}
let restorationLive=null,liveTimer=null,editorPhotoPoll=null;
function stopEditorPhotoPolling(){if(editorPhotoPoll){clearInterval(editorPhotoPoll);editorPhotoPoll=null}}
function startEditorPhotoPolling(jobId,w){stopEditorPhotoPolling();const poll=async()=>{if(!w?.isConnected||document.getElementById('restModalRoot')!==w||!w.querySelector('#restForm')){stopEditorPhotoPolling();return}const ids=items.filter(i=>i.restoration_job_id===jobId).map(i=>i.id);if(!ids.length)return;try{const fresh=await req('/rest/v1/restoration_photos?restoration_item_id=in.('+ids.join(',')+')&select=*&order=created_at.asc');const idSet=new Set(ids.map(Number));photos=[...photos.filter(p=>!idSet.has(Number(p.restoration_item_id))),...fresh];syncOpenEditorPhotos()}catch{}};poll();editorPhotoPoll=setInterval(poll,900)}
function queueLiveRefresh(){clearTimeout(liveTimer);liveTimer=setTimeout(async()=>{try{const [j,i,r,p,ph]=await Promise.all([req('/rest/v1/restoration_jobs?select=*&order=created_at.desc,id.desc'),req('/rest/v1/restoration_items?select=*&order=created_at.asc'),req('/rest/v1/restoration_routes?select=*,restoration_route_stops(*)&order=route_date.desc.nullslast,created_at.desc'),req('/rest/v1/restoration_projects?select=*&order=name.asc'),req('/rest/v1/restoration_photos?select=*&order=created_at.asc')]);jobs=j.map(normalizeContract);items=i;routes=r;projects=p;photos=ph;render();syncOpenEditorPhotos()}catch{}},120)}
function startRestorationRealtime(){if(restorationLive||!window.supabase?.createClient)return;const token=session()?.access_token||KEY,client=window.supabase.createClient(BASE,KEY,{auth:{persistSession:false},global:{headers:{Authorization:`Bearer ${token}`}}});try{client.realtime?.setAuth?.(token)}catch{}restorationLive=client.channel('restoration-live');['restoration_jobs','restoration_items','restoration_routes','restoration_route_stops','restoration_projects'].forEach(table=>restorationLive.on('postgres_changes',{event:'*',schema:'public',table},queueLiveRefresh));restorationLive.on('postgres_changes',{event:'*',schema:'public',table:'restoration_photos'},async()=>{try{photos=await req('/rest/v1/restoration_photos?select=*&order=created_at.asc');syncOpenEditorPhotos();render()}catch{queueLiveRefresh()}});restorationLive.subscribe()}
